<?php
namespace App\Livewire\Laboratory;
use App\Enums\LaboratoryOrderEstado;use App\Models\Laboratory\LaboratoryOrder;use App\Models\Laboratory\LaboratoryPackage;use App\Models\Laboratory\LaboratoryProfile;use App\Models\Laboratory\LaboratoryTest;use App\Models\Patient;use App\Services\Laboratory\LaboratoryOrderBuilderService;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Component;
class LaboratoryMassOrderManager extends Component{public array $patient_ids=[],$test_ids=[],$profile_ids=[],$package_ids=[],$summary=[];
public function process(LaboratoryOrderBuilderService $service){$this->summary=['created'=>0,'skipped'=>0,'errors'=>[]];DB::transaction(function() use($service){foreach($this->patient_ids as $patientId){try{ $exists=LaboratoryOrder::whereDate('fecha_orden',now()->toDateString())->where('patient_id',$patientId)->exists(); if($exists){$this->summary['skipped']++; continue;} $service->createOrder(['patient_id'=>$patientId,'user_id'=>Auth::id(),'fecha_orden'=>now()->toDateString(),'estado'=>LaboratoryOrderEstado::PENDIENTE->value],$this->test_ids,$this->profile_ids,$this->package_ids);$this->summary['created']++;}catch(\Throwable $e){$this->summary['errors'][]="Paciente {$patientId}: {$e->getMessage()}";}}});}
public function render(){return view('livewire.laboratory.mass-order-manager',['patients'=>Patient::orderBy('nombres_apellidos')->get(['id','nombres_apellidos']),'tests'=>LaboratoryTest::where('estado',true)->get(['id','nombre']),'profiles'=>LaboratoryProfile::where('estado',true)->get(['id','nombre']),'packages'=>LaboratoryPackage::where('estado',true)->get(['id','nombre'])])->layout('layouts.app');}
}
